ds":["ept-loan"]},{"id":"ept-b2-u05-rev1-e09","lesson_id":"ept-b2-u05-rev1","position":9,"type":"complete_word","skill":"vocabulary","prompt_es":"Escreva a palavra completa","payload":{"type":"complete_word","masked":"d_b_","hint":"dívida"},"answer":"debt","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":20,"words":["ept-debt"]},{"id":"ept-b2-u05-rev1-e10","lesson_id":"ept-b2-u05-rev1","position":10,"type":"match_pairs","skill":"vocabulary","prompt_es":"Una cada palavra ao seu significado","payload":{"type":"match_pairs","pairs":[{"left":"bargain","right":"pechincha / ótima compra"},{"left":"debt","right":"dívida"},{"left":"loan","right":"empréstimo"},{"left":"second-hand","right":"de segunda mão / usado"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["ept-bargain","ept-debt","ept-loan","ept-second-hand"]},{"id":"ept-b2-u05-l03-e01","lesson_id":"ept-b2-u05-l03","position":1,"type":"fill_blank","skill":"grammar","prompt_es":"Complete a frase","payload":{"type":"fill_blank","sentence":"I had my phone ___ last week.","translation":"Semana passada mandei consertar o meu celular.","options":["repaired","repair","repairing","to repair"]},"answer":"repaired","accepted_answers":[],"explanation_es":"Have + objeto + particípio (repaired).","difficulty":1,"recommended_seconds":15,"words":["ept-have-something-done"]},{"id":"ept-b2-u05-l03-e02","lesson_id":"ept-b2-u05-l03","position":2,"type":"fill_blank","skill":"grammar","prompt_es":"Complete a frase","payload":{"type":"fill_blank","sentence":"I'm going to get my hair ___ tomorrow.","translation":"Amanhã eu vou cortar o cabelo.","options":["cut","cutting","to cut","cuts"]},"answer":"cut","accepted_answers":[],"explanation_es":"Cut é irregular: o particípio é cut.","difficulty":1,"recommended_seconds":15,"words":["ept-have-something-done"]},{"id":"ept-b2-u05-l03-e03","lesson_id":"ept-b2-u05-l03","position":3,"type":"fill_blank","skill":"grammar","prompt_es":"Complete a frase","payload":{"type":"fill_blank","sentence":"We are having our kitchen ___ next month.","translation":"No mês que vem vamos mandar pintar a cozinha.","options":["painted","paint","painting","to paint"]},"answer":"painted","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["ept-have-something-done"]},{"id":"ept-b2-u05-l03-e04","lesson_id":"ept-b2-u05-l03","position":4,"type":"context_choice","skill":"listening","prompt_es":"Ouça e responda","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"ept.stim.b2-u5-repair","setting":"Um cliente numa loja de conserto de celulares.","speakers":[{"name":"Customer","voice":"a"},{"name":"Assistant","voice":"b"}],"rate":1,"lines":[{"speaker":"Customer","text":"Hi. I dropped my phone yesterday and I'd like to have the screen replaced."},{"speaker":"Assistant","text":"Let me see. Yes, we can do that. It's ninety dollars, and it'll be ready tomorrow."},{"speaker":"Customer","text":"Ninety? That's twice as much as I paid last time!"},{"speaker":"Assistant","text":"Last time you had a cheaper screen put in. This one is original. The cheaper ones are nowhere near as good."},{"speaker":"Customer","text":"Hmm. Is it worth it? The phone is three years old."},{"speaker":"Assistant","text":"Honestly, the older the phone, the less sense it makes. A new one costs about four hundred."},{"speaker":"Customer","text":"I can't afford a new one right now. Go ahead and replace the screen, please."}]},"question":"O que o cliente quer?","options":["Que troquem a tela do celular dele","Comprar um celular novo","Que devolvam o dinheiro dele","Consertar a tela ele mesmo"]},"answer":"Que troquem a tela do celular dele","accepted_answers":[],"explanation_es":"O cliente diz: “I’d like to have the screen replaced”.","difficulty":1,"recommended_seconds":75,"words":[]},{"id":"ept-b2-u05-l03-e05","lesson_id":"ept-b2-u05-l03","position":5,"type":"context_choice","skill":"listening","prompt_es":"Ouça e responda","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"ept.stim.b2-u5-flatmates","setting":"Dois amigos que dividem apartamento falam de dinheiro.","speakers":[{"name":"Jake","voice":"a"},{"name":"Rita","voice":"b"}],"rate":1,"lines":[{"speaker":"Jake","text":"I'm thinking of taking out a loan to buy a car."},{"speaker":"Rita","text":"Are you sure? You still have debt on your credit card."},{"speaker":"Jake","text":"I know, but the bank is offering a low interest rate at the moment."},{"speaker":"Rita","text":"Low now, but it could rise. And can you really afford the monthly payments?"},{"speaker":"Jake","text":"If I cut back on eating out, I think so."},{"speaker":"Rita","text":"Why not buy a second-hand car instead? You'd need a much smaller loan, or no loan at all."},{"speaker":"Jake","text":"That's actually a good idea. I'll have a mechanic check a few cars this weekend."}]},"question":"O que Jake vai fazer neste fim de semana?","options":["Pedir para um mecânico avaliar alguns carros","Avaliar os carros ele mesmo","Fazer o empréstimo","Vendeu o carro"]},"answer":"Pedir para um mecânico avaliar alguns carros","accepted_answers":[],"explanation_es":"Jake diz: “I’ll have a mechanic check a few cars this weekend”. Have + pessoa + verbo: outra pessoa faz.","difficulty":1,"recommended_seconds":75,"words":[]},{"id":"ept-b2-u05-l03-e06","lesson_id":"ept-b2-u05-l03","position":6,"type":"listen_choice","skill":"listening","prompt_es":"Ouça e escolha o que você ouve","payload":{"type":"listen_choice","audioText":"I had my phone repaired last week.","options":["I had my phone repaired last week.","I repaired my phone last week.","I had my phone repaired last month.","I have my phone repaired every year."]},"answer":"I had my phone repaired last week.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["ept-have-something-done"]},{"id":"ept-b2-u05-l03-e07","lesson_id":